def on_drop(event):
    # tkinterdnd2 passes an event; extract the dropped path
    data = event.data if hasattr(event, 'data') else str(event)
    # Tk wraps paths with braces if they contain spaces: {C:/path/to/file.txt}
    path = data.strip().strip("{").strip("}")
    if os.path.isfile(path) and path.lower().endswith(".txt"):
        file_var.set(path)
        try:
            pack, locale, old_tag = parse_name(path)
            status_var.set(f"Loaded: {pack} | Tag: {old_tag}")
        except ValueError:
            status_var.set("Warning: filename may not have a valid BattleTag")
    else:
        status_var.set("Dropped file is not a .txt guide")


